using namespace std;

uint64_t sqrti(uint64_t b) {
    uint64_t n = 2;
    if (b < 2) {
        return b;
    }
    uint64_t n1 = n - 1;
    uint64_t n2 = n;
    uint64_t n3 = n1;
    uint64_t c = 1;
    uint64_t d = (n3 + b) / n2;
    uint64_t e = (n3 * d + b / (uint64_t)pow(d, (uint32_t)n1)) / n2;
    while (c != d && c != e) {
        c = d;
        d = e;
        e = (n3 * e + b / (uint64_t)pow(e, (uint32_t)n1)) / n2;
    }
    if (d < e) return d;
    else return e;
}

struct Range {
    uint64_t start;
    uint64_t end;
};

struct Rects {
    uint64_t area;
    uint64_t w;
    Range rw;
    Range rh;

    static Rects New(uint64_t area) {
        uint64_t q = sqrti(area);
        Rects r;
        r.area = area;
        r.rw = {1, q};
        r.rh = {1, area};
        r.w = q;
        return r;
    }

    static Rects with_limits(uint64_t area, Range rw, Range rh) {
        uint64_t q = sqrti(area);
        uint64_t maxw = min(q, min(area / rh.start, rw.end));
        uint64_t minw = max(area / rh.end, rw.start);
        Rects r;
        r.area = area;
        r.rw = {minw, maxw};
        r.rh = rh;
        r.w = maxw;
        return r;
    }

    bool next(uint64_t &out_w, uint64_t &out_h) {
        while (w >= rw.start) {
            uint64_t cw = w;
            w -= 1;
            uint64_t h = area / cw;
            if (h < rw.start || h > rh.end || h * cw != area) {
                continue;
            }
            out_w = cw;
            out_h = h;
            return true;
